<?php require __DIR__.'/../bootstrap.php';admin_only();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO coupons(code,type,value,min_amount,usage_limit,expires_at,active) VALUES(?,?,?,?,?,?,?)')->execute([strtoupper(trim($_POST['code'])),$_POST['type'],(int)$_POST['value'],(int)$_POST['min_amount'],($_POST['usage_limit']??'')!==''?(int)$_POST['usage_limit']:null,($_POST['expires_at']??'')!==''?$_POST['expires_at']:null,1]);flash('ok','کد تخفیف اضافه شد.');redirect('admin/coupons.php');}$cs=$pdo->query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll();$title='کدهای تخفیف';require __DIR__.'/../partials/header.php';?><h1>کدهای تخفیف</h1><div class="panel"><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><div class="field"><label>کد</label><input name="code" required></div><div class="field"><label>نوع</label><select name="type"><option value="percent">درصدی</option><option value="fixed">مبلغ ثابت</option></select></div><div class="field"><label>مقدار</label><input type="number" name="value" required></div><div class="field"><label>حداقل مبلغ</label><input type="number" name="min_amount" value="0"></div><div class="field"><label>سقف استفاده</label><input type="number" name="usage_limit"></div><div class="field"><label>انقضا</label><input type="datetime-local" name="expires_at"></div><button class="btn">افزودن</button></form></div><div class="panel table-wrap"><table class="table"><tr><th>کد</th><th>نوع</th><th>مقدار</th><th>استفاده</th><th>انقضا</th></tr><?php foreach($cs as $c): ?><tr><td><?=e($c['code'])?></td><td><?=e($c['type'])?></td><td><?=$c['value']?></td><td><?=$c['used_count']?> / <?=is_null($c['usage_limit'])?'∞':$c['usage_limit']?></td><td><?=e($c['expires_at']??'-')?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
